function cellRuns(text, bold, size){
  const parts = String(text).split("\n"); const runs = [];
  parts.forEach(function(p,i){
    if (i>0) runs.push(new TextRun({text:"", break:1}));
    runs.push(new TextRun({text:p, bold:bold, font:FONT, size:size}));
  });
  return runs;
}
function makeTable(rows, widths){
  const total = widths.reduce(function(a,b){return a+b;},0);
  const trs = rows.map(function(r,ri){ return new TableRow({ tableHeader: ri===0, children: r.map(function(c,ci){
    return new TableCell({ width:{size:widths[ci], type:WidthType.DXA},
      shading: ri===0 ? {type:ShadingType.CLEAR, fill:"D9E2F3"} : undefined,
      children:[ new Paragraph({ spacing:{after:20,line:240}, children: cellRuns(c, ri===0, 18) }) ] }); })}); });
  return new Table({ columnWidths:widths, width:{size:total,type:WidthType.DXA}, rows:trs });
}
